mapper.delete:
delete from  t_std_device
        where device_id=#{deviceId,jdbcType=BIGINT}
        and custom_id=#{customId,jdbcType=VARCHAR}

mapper.select:
select
a.device_id,
a.custom_id,
a.device_code,
a.device_name,
a.alias_name,
a.device_type,
a.position_type,
a.model_id,
a.region_path,
a.up_region_id,
a.up_region_name,
a.custom_name,
a.custom_type,
a.status,
a.update_time,
a.create_time
from t_std_device a
where 1 = 1
 and a.device_id = #{deviceId, jdbcType=BIGINT}
 and a.custom_id = #{customId, jdbcType=VARCHAR}
 and a.device_code = #{deviceCode, jdbcType=VARCHAR}
 and a.device_name = #{deviceName, jdbcType=VARCHAR}
 and a.alias_name = #{aliasName, jdbcType=VARCHAR}
 and a.device_type = #{deviceType, jdbcType=INTEGER}
 and a.position_type = #{positionType, jdbcType=VARCHAR}
 and a.model_id = #{modelId, jdbcType=BIGINT}
 and a.region_path = #{regionPath, jdbcType=VARCHAR}
 and a.up_region_id = #{upRegionId, jdbcType=BIGINT}
 and a.up_region_name = #{upRegionName, jdbcType=VARCHAR}
 and a.custom_name = #{customName, jdbcType=VARCHAR}
 and a.custom_type = #{customType, jdbcType=INTEGER}
 and a.status = #{status, jdbcType=INTEGER}
 and a.update_time = #{updateTime, jdbcType=TIMESTAMP}
 and a.create_time = #{createTime, jdbcType=TIMESTAMP}

select
*
from t_std_device a
left join (select * from t_std_device_attr
left join (select dict_code as code1 ,dict_note as deviceModelName from t_dict_business) e on device_model = e.code1
left join (select dict_code as code2,dict_note as deviceVendorName from t_dict_business) f on device_vendor=f.code2
left join (select dict_code as code3,dict_note as voltageLevelName from t_dict_business) g on voltage_level=g.code3
) b on a.device_id = b.device_id
left join (select model_id ,model_name as modelName from t_std_metemodel) d on d.model_id=a.model_id
left join (select dict_code as code4,dict_note as deviceTypeName from t_dict_business) h on h.code4 = a.device_type
where 1=1
 and a.device_id = #{deviceId, jdbcType=BIGINT}
 and a.custom_id = #{customId, jdbcType=VARCHAR}
 and a.device_code = #{deviceCode, jdbcType=VARCHAR}
 and a.device_name like concat('%',#{deviceName, jdbcType=VARCHAR},'%') 
 and a.alias_name = #{aliasName, jdbcType=VARCHAR}
 and a.device_type like concat('%', #{deviceType, jdbcType=INTEGER},'%')
 and a.position_type = #{positionType, jdbcType=VARCHAR}
 and a.model_id = #{modelId, jdbcType=BIGINT}
 and a.region_path = #{regionPath, jdbcType=VARCHAR}
 and a.up_region_id = #{upRegionId, jdbcType=BIGINT}
 and a.up_region_name = #{upRegionName, jdbcType=VARCHAR}
 and a.custom_name = #{customName, jdbcType=VARCHAR}
 and a.custom_type = #{customType, jdbcType=INTEGER}
 and a.status = #{status, jdbcType=INTEGER}
 and a.update_time = #{updateTime, jdbcType=TIMESTAMP}
 and a.create_time = #{createTime, jdbcType=TIMESTAMP}
 and b.device_model = #{deviceModel, jdbcType=INTEGER}
 and b.pms_type = #{pmsType, jdbcType=VARCHAR}
 and b.pms_id = #{pmsId, jdbcType=VARCHAR}
 and b.device_vendor = #{deviceVendor, jdbcType=VARCHAR}
 and b.production_date = #{productionDate, jdbcType=TIMESTAMP}
 and b.used_time = #{usedTime, jdbcType=TIMESTAMP}
 and b.disable_date = #{disableDate, jdbcType=TIMESTAMP}
 and b.last_maintenance = #{lastMaintenance, jdbcType=TIMESTAMP}
 and b.maintenance_count = #{maintenanceCount, jdbcType=VARCHAR}
 and b.organization = #{organization, jdbcType=VARCHAR}
 and b.department = #{department, jdbcType=VARCHAR}
 and b.responsible_person = #{responsiblePerson, jdbcType=VARCHAR}
 and b.latitude = #{latitude, jdbcType=VARCHAR}
 and b.longitude = #{longitude, jdbcType=VARCHAR}
 and b.ip = #{ip, jdbcType=VARCHAR}
 and b.port = #{port, jdbcType=INTEGER}
 and b.voltage_level = #{voltageLevel, jdbcType=VARCHAR}
 and b.sequence_point = #{sequencePoint, jdbcType=VARCHAR}
 and b.real_code like concat('%', #{realCode, jdbcType=VARCHAR},'%')
 and b.address = #{address, jdbcType=VARCHAR}
GROUP BY a.device_id

select
a.device_id,
a.custom_id,
a.device_code,
a.device_name,
a.alias_name,
a.device_type,
a.position_type,
a.model_id,
a.region_path,
a.up_region_id,
a.up_region_name,
a.custom_name,
a.custom_type,
a.status,
a.update_time,
a.create_time
from t_std_device a
where 1 = 1
 and a.device_id = #{deviceId, jdbcType=BIGINT}
 and a.custom_id = #{customId, jdbcType=VARCHAR}
 and a.device_code = #{deviceCode, jdbcType=VARCHAR}
 and a.device_name = #{deviceName, jdbcType=VARCHAR}
 and a.alias_name = #{aliasName, jdbcType=VARCHAR}
 and a.device_type = #{deviceType, jdbcType=INTEGER}
 and a.position_type = #{positionType, jdbcType=VARCHAR}
 and a.model_id = #{modelId, jdbcType=BIGINT}
 and a.region_path = #{regionPath, jdbcType=VARCHAR}
 and a.up_region_id = #{upRegionId, jdbcType=BIGINT}
 and a.up_region_name = #{upRegionName, jdbcType=VARCHAR}
 and a.custom_name = #{customName, jdbcType=VARCHAR}
 and a.custom_type = #{customType, jdbcType=INTEGER}
 and a.status = #{status, jdbcType=INTEGER}
 and a.update_time = #{updateTime, jdbcType=TIMESTAMP}
 and a.create_time = #{createTime, jdbcType=TIMESTAMP}

select , e.dict_note as deviceModelName, f.dict_note as deviceVendorName, g.dict_note as voltageLevelName, d.model_name as modelName, h.dict_note as deviceTypeName, l.pic_real_path, k.region_name as upRegionName from t_std_device a left join t_std_device_attr b on a.device_id = b.device_id left join t_dict_business e on device_model = e.dict_code left join t_dict_business f on device_vendor=f.dict_code left join t_dict_business g on voltage_level=g.dict_code left join t_std_metemodel d on d.model_id=a.model_id left join t_dict_business h on h.dict_code = a.device_type left join t_std_region k on a.up_region_id = k.region_id left join t_device_type_img l on a.device_type = l.type_id where 1=1
and a.up_region_id in
#{upRegionIds,jdbcType=BIGINT}
and a.device_name like concat('%',#{deviceName, jdbcType=VARCHAR},'%') and a.device_type like concat('%', #{deviceType, jdbcType=INTEGER},'%') and b.real_code like concat('%', #{realCode, jdbcType=VARCHAR},'%') and a.device_id in
#{deviceId,jdbcType=BIGINT}
group by a.device_id order by a.device_id desc

SELECT a.region_id AS Id, a.region_name AS label, a.up_region_id AS upId, b.region_name AS upName, "region" AS infoType
    FROM t_std_region a
    LEFT JOIN t_std_region b ON a.up_region_id = b.region_id;

SELECT a.region_id AS Id, a.region_name AS label, a.up_region_id AS upId, b.region_name AS upName, "region" AS infoType
FROM t_std_region a
LEFT JOIN t_std_region b ON a.up_region_id = b.region_id;

mapper.update:
UPDATE t_std_device
SET model_id = #{modelId,jdbcType=BIGINT}
WHERE
device_id = #{deviceId,jdbcType=BIGINT}
AND custom_id = #{customId,jdbcType=BIGINT}
LIMIT 1
